def add(sub,b,title,why,facts,static,analysis,trap,mains,src='PRS',day=0,ap=False,p='P1',precision=None):
 J.append(dict(id=f'E16-2609-{len(J)+1:03}',date=f'2026-09-{day:02}' if day else '2026-09-30',date_precision=precision or ('day' if day else 'month'),subject=sub,block=b,title=title,why=why,facts=facts.split('|'),static_link=static,analysis=analysis.split('|'),trap=trap,mains=mains,priority=p,ap=ap,sources=['E16-'+x for x in src.split(',')],status='Historical September-indexed selected research. Drafts, approvals, future commencement and thematic revision distinguished; not complete-month/current-law/implementation certification.',checked='2026-11-07',evidence_access='Passages actually read and primary/secondary limits are in the source-access registry. Static links, analysis and exam prompts are original guidance.'))
add('Economy','01 · External balance and financial regulation','Q1 BoP: a goods deficit is not the current-account deficit','RBI released preliminary April–June FY2026–27 data on1September. Services and transfers substantially offset the merchandise deficit.','CAD is US$4.2billion,0.5%ofGDP,versus0.4%a year earlier;merchandise deficit isUS$86.1billion.|Netservices receipts areUS$51.6billion;netprimaryincome is−US$10.5billion and netsecondaryincome+US$40.8billion. Personaltransfer RECEIPTS42.9billion are not identical to netsecondaryincome.|NetFDI inflow6.1billion coexists with netFPI outflow9.6billion;reserves deplete8.1billion on a BoPbasis.','Currentaccount includes goods,services and income;financial flows and reserveassets follow accounting conventions that must be preserved.','The RBI table includes reserves in the capital/financial aggregate;PRS presents nonreserve flows separately. Do not compare unlike totals or read the positive reserveasset entry as accumulation.|For AP,connect services exports,remittances and energy-import exposure without assigning the national CAD to the state. Preliminary flow estimates differ from weekly reserve stocks affected by valuation.','September release covers April–June;8.1billion is BoP reserve depletion,not an increase.','Explain how services and remittances cushion India’s external imbalance.','BOP',1)
add('Economy','02 · Digital payments and consumer interests','UPI MDR: merchant pricing is not a consumer transfer fee','The official FAQ dated15September describes selective MDR effective15October2026. It separates merchant transactions,exemptions and consumer protection.','Eligible P2M transactions above₹2,000 attract0.4%,capped₹300 at₹75,000and above. P2P transfers and ordinary payer use remain free.|Eligible P2PM/small merchants receiving up to₹1lakh monthly throughUPIQR and automated recurring instructions retain zeroMDR;category conditions matter.|Specified thin-margin sectors use₹5 above₹2,000;capital-market transactions use0.02%,cap₹300. Credit-linkedUPI follows separate product rules.','MDR is a merchant acceptance cost. A direct surcharge prohibition differs from the economic incidence of costs through margins or general prices.','Payment infrastructure needs resilient funding,but inclusion depends on transparent categorisation,complaints and actual merchant compliance. Avoid repeating the FAQ’s economic assertion that prices cannot rise as a proven outcome.|At₹50,000the general0.4%fee is₹200;at₹1lakh the cap makes it₹300. AP small businesses need accurate exemption advice,not a message that every UPI transfer is charged.','This is not a0.4%fee on every consumer or person-to-person transfer.','How should payment-system sustainability be balanced with small-merchant inclusion?','UPI',15)
add('Economy','01 · External balance and financial regulation','Insurance distribution consultation: change incentives,not just disclosures','PRS reviews IRDAI’s23September consultation,with comments until25October. The regulator’s page exposed a viewer,but its substantive paper was not independently read.','Proposals include differentiated commission caps and a five-year glide path for lower management-expense limits.|Distributor categories would be simplified;compulsory bank/NBFC bundling would be prohibited under the proposal.|Mis-selling disclosure,commission clawback and an interoperable public insurance registry are proposed safeguards,not verified final operative rules.','Information asymmetry and principal–agent problems arise when sales rewards conflict with customer suitability and long-term value.','Assess persistency,claim outcomes,exclusions and affordable protection alongside premium growth. Commission caps can reduce distorted incentives but may also affect outreach in underserved areas.|For AP,connect bancassurance complaints and financial literacy to accessible redress. A registry needs privacy,accuracy and correction safeguards;digitisation alone cannot eliminate mis-selling.','A consultation proposal is not a final cap or an automatic refund to every policyholder.','Can insurance-distribution reform align commercial incentives with consumer welfare?','PRS,IRDAI',23)
add('Economy','01 · External balance and financial regulation','Personal guarantors: strengthen creditor decisions without erasing due process','IBBI’s discussion paper proposes four safeguards for personal-guarantor insolvency. Opening primary passages and PRS explain the proposals;comments close3October.','A related party would receive nil voting share,with the relationship identified in the creditor list.|Earlier scrutiny of avoidance transactions would examine preferential,undervalued,fraudulent or extortionate arrangements before repayment-plan decisions.|Registered valuation and recorded creditor deliberations/commercial rationale are proposed;these later details rely onPRS rather than a complete primary-paper reading.','A personal guarantee differs from the company’s own debt resolution. Claim admission,voting rights,asset value and recovery are distinct concepts.','Transparent reasoning helps detect collusive settlements without substituting arbitrary official preference for legitimate creditor judgment. Independent valuation needs reliable assets and realistic realisability assumptions.|For AP enterprises,preserve both credit discipline and fair process. Proposed related-party voting restrictions do not mean all guarantees are cancelled or every family member automatically loses property.','A discussion paper does not itself amend every repayment plan already under consideration.','Why are conflict-of-interest controls essential in personal-guarantor insolvency?','IBBI,PRS',12,p='P2')
add('Polity & Governance','01 · Financial security and procedural fairness','Money-mule draft: freezing fraud proceeds needs a reviewable process','RBI’s11September release invites comments on draftKYC changes following an August SupremeCourt direction. Detailed timelines below are PRS-reviewed proposals,not independently read finalSOP.','A suspected transaction or account may face a temporary debit hold,with immediate notice and an opportunity to explain.|The proposed explanation period is20days;review follows within10days after an explanation or30days from hold if none arrives.|Banks would need internal policies,technology,communication templates,cyber-fraud portal links and grievance redress;comments close2October.','A debit hold differs from seizure,confiscation or a criminal conviction. Account-level restrictions can affect legitimate livelihood receipts.','Target the suspect amount where justified,maintain reasoned records and ensure timely escalation/removal according to lawful procedure. Automated suspicion scores should not become irrebuttable evidence.|For AP residents affected by cyber fraud,accessible notice,assisted response and coordination with police can protect victims and innocent recipients. This note does not offer a universal legal release deadline under unread final rules.','Draft timelines are not a blanket final authorisation for indefinite account freezes.','How can banks prevent cyber fraud while safeguarding innocent account holders?','KYC,PRS',11)
add('Economy','03 · Fiscal federalism and public finance','WMA advisory: liquidity support is not a fiscal grant','RBI’s29September release says the committee’s recommendations will be examined. Proposed limits come fromPRS;the full advisory report was not independently inspected.','AggregateWMA is recommended to rise₹61,008crore to₹67,839crore,with annual revision capped at4%under the proposed approach.|SpecialDrawingFacility against eligible sinking-fund investments is proposed to rise50%to75%.|Recommended overdraft limits tighten from14to10consecutive working days and36to30working days per quarter;these are not verified implemented changes.','Here SDF means SpecialDrawingFacility for states,not the monetary-policy StandingDepositFacility. WMA bridges temporary cash mismatches.','Spread market borrowing more evenly and improve cash forecasting so liquidity facilities do not mask persistent structural deficits. Contributing to sinking/guarantee funds can strengthen fiscal resilience.|For AP,assess cash management,contingent liabilities and debt servicing separately. A higher national recommended ceiling does not establish an AP-specific entitlement or debt waiver.','Committee recommendations are not revised operative limits;WMA is repayable liquidity,not a grant.','Distinguish state cash-flow management from long-term fiscal sustainability.','WMA,PRS',29)
add('Society & Welfare','01 · Labour and health protection','EPFO wage ceiling: read the notified statutory purpose','The complete17September Gazette notifies₹25,000per month forChapterIII of the CodeonSocialSecurity2020,effective publication. It supersedes the29May notification.','The reviewed change raises the wage ceiling from₹15,000to₹25,000for the covered provident-fund framework.|The ceiling helps determine mandatory coverage at joining under applicable scheme conditions;it is not every employee’s required contribution amount.|Provident fund,pension and insurance coverage have specific rules;the short notification does not independently establish every benefit calculation or membership exception.','A coverage ceiling differs from minimum wage,take-home pay,contribution rate and pension benefit. Statutory wage definitions also matter.','Formal coverage can improve security while changing payroll compliance and household cash flows. Assess actual enrolment,remittance and portable access rather than merely counting eligible workers.|For APMSMEs and employees,provide clear wage-definition guidance and accessible correction of employer records. Avoid promising a₹25,000monthly pension or assuming every worker above the ceiling must leave existing membership.','₹25,000is a notified wage ceiling,not a universal minimum salary or pension.','How can social-security expansion combine wider coverage and effective compliance?','EPFO,PRS',17)
add('Economy','04 · Energy systems and industrial capability','Green Energy Corridor III: integrate generation,transmission and storage','The30September Cabinet release approves intra-state network and storage support throughFY2032–33. Targets,financial support and implementation modes remain distinct.','Headline project outlay is₹1,86,405crore with central support₹54,082crore.|The design enables evacuation of up to135GWrenewables and deployment of50GWhBESS;GW andGWh measure different quantities.|Greenfield transmission uses tariff-based competitive bidding/BOOM;brownfield strengthening is cost-plus,with StateTransmissionUtilities overall implementers.','Power capacity differs from stored energy and from annual electricity delivered. Transmission investment is necessary but not equivalent to generation commissioning.','The primary component amounts do not exactly reconcile with the headline total;the unresolved₹27crore difference is recorded rather than silently repaired. Headline totals are quoted without an invented breakdown.|For AP,plan evacuation,corridor rights,dispatch,storage cycling and affordability together. Central approval does not certify a named state project allocation or completed connection.','50GWh is storage energy,not50GWgeneration or guaranteed continuous135GWoutput.','Why must renewable expansion be assessed as a system-integration challenge?','GEC',30)
add('Economy','04 · Energy systems and industrial capability','Petroleum amendment draft: decriminalisation is offence-specific','PRS reviews a draft amendment to the PetroleumAct1934,with comments until30October. It changes proposed penalties and critical-infrastructure protection rather than uniformly removing sanctions.','The draft differentiates operating without a licence from specified compliance contraventions.|Some licence-condition/statement contraventions would face civil penalties and possible licensing consequences.|Critical petroleum infrastructure would receive a special damage-related framework;the primary draft was not independently read,so this note avoids personalised penalty advice.','Decriminalisation changes sanction design;it does not mean deregulation,automatic legalisation or immunity from civil liability.','Match sanctions to harm,culpability and enforcement capacity. Clear standards,inspections,appeals and credible recovery matter more than a large maximum fine alone.|For AP fuel storage,refining and pipelines,connect business facilitation with emergency preparedness and worker/community safety. A draft is not a new operative licence condition or completed statutory amendment.','The proposal does not decriminalise every petroleum offence.','How should economic regulation distinguish procedural breaches from serious safety risks?',p='P2')
add('Polity & Governance','02 · Digital markets and accountable regulation','E-commerce amendment: notification now,commencement in2027','The inspected Gazette’s9September notification makes amendments effective1January2027. PRS’s summary is supplemented by the primary price-reference definition.','Sponsored listings must be clearly identified and misleading search manipulation prohibited under the amendments.|A displayed price reduction must reference the prior price,defined in the inspected passage as the lowest price over the preceding30days.|Platforms must address dark patterns through annual self-audit and disclosures;the rules also address seller information and data use.','Consumer law,data governance and competition policy overlap but are not interchangeable. Advertising disclosure and ranking integrity affect informed choice.','A fake reference price can manufacture a discount even without changing the final bill. Reliable audits need evidence,complaints and enforcement rather than a self-declared certificate alone.|For AP small sellers,transparent ranking and accessible dispute channels can reduce platform dependence. Do not treat these future provisions as already operative inSeptember or infer that all loyalty programmes are banned.','1January2027is commencement;September is notification.','Can transparency obligations correct power imbalances in online marketplaces?','ECOM,PRS',9)
add('International Relations','01 · Multilateral institutions','BRICS NewDelhi declaration: cooperation is not a customs union','PRS reviews the12–13September summit and NewDelhiDeclaration. The attempted MEA page returned only navigation,so no complete primary-declaration reading is claimed.','The reviewed agenda includes greater developing-country representation and international-security/humanitarian positions.|Cooperation spans infectious-disease early warning,AI,cybersecurity and quantum technologies.|The farmer-centric agro-inputs/genetic-resources information network is described as non-binding;magazine extra initiatives are not all independently verified here.','BRICS is a cooperation grouping,not automatically a common-currency area,military alliance or supranational legislature. Membership,partnership and outreach participation differ.','Evaluate institutional follow-through,financial capacity and divergent national interests. Local-currency cooperation does not by itself eliminate dollar use or settlement risk.|For India,strategic autonomy requires issue-based coordination alongside wider partnerships. A declaration’s aspiration is not a legally enforceable entitlement for every producer or an already operational joint system.','A non-binding network is not a treaty-backed common agricultural market.','Assess BRICS as a platform for global-governance reform.',day=13)
add('International Relations','02 · Bilateral economic relationships','India–Belgium: turn diplomatic mechanisms into implementation','PRS reviews the Belgian PrimeMinister’s visit and agreements. Primary joint-statement bodies were not independently inspected in this batch.','The reviewed cooperation areas include defence,renewable energy,transnational organised crime/cybercrime and diplomatic training.|A fast-track investment mechanism,consular dialogue and institutionalised business forum are announced.|Doubling bilateral trade within five years is a target,not a verified realised trade increase.','Belgium is anEU member;bilateral facilitation must be distinguished fromEU-level trade competences and a completed free-trade agreement.','Mechanisms can resolve bottlenecks only if agencies have mandates,timelines and escalation routes. Assess actual investment,technology partnerships and legal safeguards rather than the count ofMoUs.|For AP,identify possible logistics,energy and knowledge linkages without asserting a new Belgian project sanction. Diplomatic training or consular cooperation does not create unrestricted migration or automatic professional recognition.','A bilateral trade target is not already achieved commerce or proof that an India–EUFTA is operational.','What makes investment-facilitation mechanisms effective beyond joint statements?',p='P2')
add('Agriculture','01 · Prices and farm institutions','Rabi MSP2027–28: preserve the season and cost concept','The30SeptemberCCEA release sets sixMSPs for a future marketing season. An announced price is not proof of universal procurement at that price.','Rates perquintal:wheat₹2,610,barley₹2,286,gram₹5,958,lentil₹7,390,mustard/rapeseed₹6,613,safflower₹7,215.|Absolute increases are₹25,₹136,₹83,₹390,₹413and₹675respectively;safflower has the largest increase here.|The cost footnote includes paid-out costs and imputed family labour;it must not be equated automatically with comprehensiveC2cost.','MSPannouncement,procurement access,quantity purchased and realised farmgate price are different stages. Percentage increase differs from margin over production cost.','Crop diversification needs credible markets,water suitability,storage and processing as well as a higherMSP. Procurement geography and quality requirements influence who benefits.|For AP,examine local pulses/oilseeds economics without assuming every farmer can sell unlimited output to government. Compare farmer income after costs,not only nominal price increases.','2027–28is the marketing season;₹2,610is perquintal,not pertonne.','Why areMSPincreases insufficient by themselves to secure farm incomes?','MSP',30)
add('Security','01 · Defence acquisition and strategic capability','DAC approval: acceptance of necessity precedes procurement','The7SeptemberDAC release approves proposals of about₹1.10lakhcrore in principle. It expressly describesAcceptanceofNecessity,not signed delivery contracts.','Army items includeCBRNrecce vehicles,mobility,minelaying,helicopters and bridge systems.|Navy proposals includeArudhra air-route surveillance radars and marine gas turbines;AirForce measures include ground-based multipurpose jammers andDEFSAC.|Approximately98%of planned procurement is to come from Indian industry;this is not independently verified98%domestic content in every subsystem.','AoN,request for proposals,trial/qualification,contracting and delivery are separate acquisition stages. Indigenous procurement differs from indigenous intellectual property.','Assess lifecycle support,reliability,interoperability and transparent milestone execution. Long procurement cycles can weaken readiness despite large approval totals.|For AP industrial suppliers,testing access,qualified manufacturing and payment predictability matter. Avoid converting a national approval into a confirmed localfactory order or realised employment.','₹1.10lakhcrore is estimated approved procurement,not audited expenditure or delivered capability.','How should defence acquisition be evaluated beyond headline approvals?','DAC',7)
add('Society & Welfare','01 · Labour and health protection','Allied-health registration: credentials and continuing competence','PRS reviews regulations published inSeptember. The primary notification itself is dated31August;opening Gazette definitions/status were inspected,not all later clauses.','The reviewed scheme combines recognised qualifications,exit examination and state registration,with five-year validity.|Renewal requires15CPDhours annually and75overfiveyears,with no more than50%online,according toPRS.|Reasoned refusal and appeal processes are provided;interim,temporary and provisional registration have distinct defined meanings.','Professional registration is different from an educational institution’s recognition or a guarantee of clinical competence in every task.','Protect patients through credible training,supervised practice,updated skills and complaints oversight. Registration databases need correction,privacy and accessible verification.|For AP training institutions and employers,check the applicable profession,qualification and state-council arrangements. Do not mislabel the31August notification as issued on a guessedSeptember day or treat all definitions as interchangeable licences.','75hours overfiveyears does not replace the annual15hour requirement.','How can professional regulation improve health workforce quality without arbitrary exclusion?','ALLIED,PRS')
add('Society & Welfare','02 · Food safety and public accountability','Food laboratory amendments: start date matters as much as deadlines','The14September notification,inspected in the Gazette,makes amendments effective1April2027. This future commencement is missing from a casual reading of the monthly headline.','Regulatory food-sample reports and referral reports generally have14day timelines after receipt.|Imported-food sample reports have a5day timeline under the specified framework;delays require reasons to designated authorities.|FSSAImanuals guide analysis;where a parameter’s method is unavailable,validated methods from recognised sources may be used.','Sample collection,chain of custody,validated analysis and a signed report jointly support defensible regulatory action.','Speed without laboratory quality can create false reassurance or unjustified penalties. Improve staffing,calibration,reference materials and sample logistics alongside timelines.|For AP,connect market surveillance and port-related food checks to reliable evidence and appeals. A laboratory deadline does not itself establish that a tested product is safe or that every delayed report is void.','The amendments commence1April2027,not immediately onSeptember notification.','How can food-safety systems combine timely testing and scientific reliability?','FOOD,PRS',14)
add('Environment','01 · Pollution and climate governance','Stubble compensation draft: link deterrence with alternatives','PRS reviews draftNCR/adjoining-area compensation rules,with comments until7November. The geographic scope and consultation stage must be retained.','Proposed permitted uses include residue-management technology,crop diversification,biomass infrastructure,research and training.|A land-record mark would remain15months,with extension for specified repeat/nonpayment situations under the draft.|The primary draft was not independently read;no claim is made that these provisions already apply nationwide or replace all existing rules.','Environmental compensation differs from criminal punishment and from proof of individual culpability. Crop residues have agronomic and economic uses.','Farmers need feasible machines,collection logistics,markets and time windows,not only penalties. Safeguards against erroneous marking and transparent use of collected money are important.|For AP,use comparative residue-management lessons rather than presenting anNCRdraft as anAPorder. Evaluate air-quality outcomes and verified non-burning practices,not revenue collected alone.','A geographically scoped draft does not establish a nationwide operative15month marking rule.','How should crop-residue policy combine environmental responsibility and farm viability?',p='P2')
add('Polity & Governance','03 · Land governance and service delivery','DILRMP3.0: a LandStack does not adjudicate every title','The9SeptemberPIB release previews the10September guidelines launch;PRS subsequently reports release. The primary calls the anticipated outlay₹565.50crore,rounded₹566crore inPRS.','The five-year2026–31central-sector roadmap links cadastral maps,ownership information,registration and revenue-court cases.|ULPIN/Bhu-Aadhaar assigns a14digit parcel identifier;it identifies a parcel,not the person’s Aadhaar account.|Paperless registration,georeferenced maps and integrated case management are planned;the full operational guidelines were not independently read.','Record digitisation,mutation,registered conveyance and judicial title determination have distinct legal functions. Interoperability is not automatic correctness.','Correct legacy errors through notice,assisted claims and appeal before relying on automated services. Women,tenants,customary users and common lands need safeguards.|For AP,link revenue,registration and local-body systems with clear responsibility and auditable corrections. Count reliable citizen transactions and resolved disputes,not merely uploaded maps.','₹565.50crore is the primary anticipated national outlay,not anAPgrant or completed spending.','What safeguards make integrated land-information systems trustworthy?','DIL,PRS')
add('Polity & Governance','02 · Digital markets and accountable regulation','Television advertisement limits: repeal has a specific scope','PRS reportsTRAI’s repeal of the2012advertisement-duration regulations after the corresponding cable-rule ceiling was removed inAugust. This is a legal-instrument change,not blanket deregulation.','The repealed framework had a12minute-per-hour advertising ceiling.|It also addressed minimum advertisement gaps and advertising during breaks in live sporting action.|The complete primary repeal instrument was not independently inspected;other consumer,content and advertising laws cannot be presumed repealed.','A rule and a regulator’s regulation are different delegated instruments. Removing one quantitative restriction does not remove every substantive obligation.','Evaluate viewer experience,competition,subscription economics and transparent commercial labelling. Market freedom can improve flexibility while increasing the need for complaint mechanisms and clear sponsorship identification.|ForMains,distinguish business-model reform from immunity for misleading advertisements. A short monthly summary cannot establish every broadcaster’s final compliance position.','Repealing a duration ceiling is not legal permission for every form of harmful or deceptive advertising.','How should broadcasting regulation balance commercial flexibility and viewer interests?',p='P2')
add('Polity & Governance','02 · Digital markets and accountable regulation','Commercial calls: verify consent rather than presume a lasting relationship','PRS reviewsTRAI’s third amendment to commercial-communications regulations. It addresses automated calling,inquiry-based contact and blanket spam labels.','Application-to-person calls must be declared with relevant number details to providers;the reviewed charging ceiling is5paisa perminute subject to designated-series exceptions.|Inquiry-based contact is reduced fromthreemonths tosevendays,with written/digital verifiable inquiry records.|Call-management apps may not blanket-block/tag specified commercial series,but individuals retain device-level blocking/filtering choices.','A marketing communication differs from a service or transaction message. Consent must have a defined purpose and evidentiary trail.','Protect users from harassment while preserving legitimate notifications. Audit sender records,complaints and enforcement rather than relying solely on caller-ID labels or a broad claim of prior interest.|For APdigital inclusion,offer accessible reporting and ensure less digitally skilled users can withdraw unwanted contact. A compliance category is not proof every individual call is welcome or genuine.','An inquiry does not create unlimited permanent marketing permission;individual blocking remains distinct from app-wide blanket action.','How can telecom regulation protect consent without obstructing useful communication?',p='P2')
add('Security','02 · Industrial safety and resilient infrastructure','Steel safety council: institutions must learn from near misses','PRS reviews the proposedSteelIndustrySafetyCouncil and supporting directorate. The primary constitution/order and actual staffing were not independently inspected.','The Council is designed as an apex safety body chaired by theSteelSecretary,with industry and technical/statutory representation.|Its functions include reviewing safety conditions,standards,accidents and near misses.|The technical directorate would support audits,investigations,training and emergency preparedness;announcement is not proof of completed inspection nationwide.','Process safety concerns major hazards and system failures as well as individual protective equipment. Near-miss reporting can reveal latent risks before fatalities occur.','Independent learning needs protected reporting,competent investigators and credible implementation of corrective actions. Industry participation should not dilute accountability for worker safety.|For APindustrial areas,coordinate factories,emergency services,health agencies and environmental oversight. Monitor closure of safety findings and contractor training,not only the number of meetings or circulars.','Creation of a council does not establish that all plants are safe or all incidents have been investigated.','What makes industrial-safety oversight effective beyond formal compliance?',p='P2')
add('Economy','04 · Energy systems and industrial capability','Rare-earth magnets: resources do not equal industrial capability','Selected September magazine passages revisit a manufacturing scheme explicitly approved in November2025. This is value-chain consolidation,not a fresh September scheme sanction.','Sintered permanent magnets support electric motors,wind equipment,electronics and defence applications.|Mining,chemical separation,metal/alloy production and magnet manufacturing require distinct technologies and environmental controls.|Heavy rare-earth availability and safe management of radioactive-associated minerals are constraints;unverified reserve and capacity totals are withheld.','Criticality depends on supply concentration,substitutability and strategic use,not just geological rarity. Resources differ from commercially recoverable reserves.','Map each production bottleneck and develop recycling,skills and reliable offtake. Owning ore does not eliminate dependence on imported separation or alloy technology.|For AP coastal-mineral contexts,do not equate a beach-sand resource with permission to mine or a commissioned magnet factory. Industrial policy must include safeguards and measurable domestic capability.','November2025approval is not a new September2026announcement;resource tonnage is not magnet output.','How can India build a secure rare-earth magnet value chain?','DRISHTI',p='P2')
add('Economy','05 · Technology,productivity and inclusive growth','Real-world asset tokenisation: digital claims need legal foundations','The magazine discusses proposals for tokenising assets,including land. Primary proposed state legislation and alleged market launches were not independently inspected;this note teaches the concept without certifying enactment.','A token can represent an ownership or economic claim linked to an asset;the underlying legal right must be defined.|Fractional claims and programmable settlement can alter transfer mechanics,but cannot automatically cure disputed ownership.|Custody,identity,redemption,stamp duty,tax and regulatory jurisdiction remain important even with a distributed ledger.','A blockchain entry,a registered deed and a court-recognised property right are not interchangeable. Atomic settlement does not remove every counterparty or operational risk.','Credible systems need accurate off-chain records,clear investor rights and procedures for fraud,lost keys and court orders. Irreversibility is not always a consumer-protection advantage.|For AP,land-record modernisation can improve information without automatically authorising securities issuance or fractional property trading. Separate technical possibility from legal permission.','Tokenisation is not automatic conclusive title or a guarantee that every token is a lawful investment.','What legal and institutional safeguards are needed for asset tokenisation?','DRISHTI',p='P2')
add('Economy','06 · Logistics and regional production','Dedicated freight corridors: integration matters beyond track length','Selected magazine passages review freight corridors and proposed links involving Vijayawada. Exact operational totals and construction status were not independently verified in this batch.','Dedicated freight tracks can separate heavy goods movements from passenger traffic and improve reliability.|DFCCIL is a specialised railway-sector implementation institution;corridors require terminals,port links and last-mile connectivity.|The reviewed EastCoast and North–South proposals include Vijayawada;proposal is not proof of completed construction or a new September sanction.','Transport capacity,logistics cost and supply-chain reliability differ. Double-stack operations require compatible clearances and route infrastructure.','Evaluate terminal dwell time,loading access,land acquisition and industrial demand rather than kilometres alone. Modal shift can reduce emissions,but depends on actual cargo capture and efficient operations.|For AP ports and producers,compare road–rail integration and affordable access for smaller shippers. Do not treat every proposed corridor as operational or assign all national logistics savings to a local project.','A proposed Vijayawada connection is not a verified commissioned freight corridor.','How can integrated logistics improve regional competitiveness?','DRISHTI',p='P2')
add('Agriculture','02 · Sustainable livelihoods and resource use','Bamboo economy: forest location changes the legal context','September magazine discussion around WorldBambooDay revisits cultivation,value addition and rural livelihoods. Exact employment and scheme-achievement totals are not independently reproduced.','Bamboo belongs botanically to the grass family.|The2017forest-law change removed bamboo grown outside forest areas from the relevant definition of tree;it does not abolish all forest controls.|Value chains include planting material,treatment,engineered products,crafts and marketing;cluster support is broader than simple plantation expansion.','Botanical classification and a statute’s regulatory definition need not be identical. Forest-grown and nonforest-grown resources can face different legal conditions.','Assess suitable species,long production cycles,quality,durable demand and ecological effects. A fast-growing plant is not automatically a profitable or universally low-impact commodity.|For AP tribal and rural enterprises,build processing and buyer access with rights safeguards. Avoid promoting plantations on common lands without consent or treating every bamboo product as equally sustainable.','The2017change did not make all harvesting inside forests unrestricted.','Can bamboo value chains support inclusive rural industrialisation?','DRISHTI',p='P2')
add('Economy','05 · Technology,productivity and inclusive growth','Middle-income trap: move from accumulation to productivity','The September compilation discusses India’s growth challenge. This is analytical revision,not a newly declared official classification or a prediction that slower growth is inevitable.','The middle-income-trap concept concerns difficulty sustaining convergence after earlier gains from labour shifts and capital accumulation.|Innovation,skills,competition and institutional quality become important as low-cost advantages narrow.|Aggregate GDP rank,per-capita income,productivity and household welfare measure different outcomes.','Growth accounting separates capital,labour and productivity contributions. Structural transformation requires workers to move into more productive activities,not only cities.','Improve learning,healthy labour-force participation,reliable infrastructure and competitive markets while supporting innovation. Protected firms can accumulate scale without becoming internationally productive.|For AP,assess job quality,regional diversification and realised private investment rather than equating a largeMoU pipeline with higher wages. Inclusive productivity growth also depends on women’s participation and accessible urban services.','A larger aggregate economy does not automatically imply high per-capita income or broad prosperity.','What reforms help economies sustain convergence at middle-income levels?','DRISHTI',p='P2')
add('Security','03 · Financial crime and institutional response','Digital hawala: technology changes channels,not the laundering problem','Selected magazine passages discuss a FATF review of underground banking. Exact survey percentages were not independently checked against the original report.','Informal value-transfer networks can settle obligations through intermediaries without moving the same physical cash across borders.|Digital channels may combine encrypted communication,virtual assets and formal financial entry/exit points.|Legitimate remittances,unlicensed transfer activity and criminal money laundering require careful legal/evidentiary distinction.','Placement,layering and integration are analytical laundering stages,not a requirement that every case uses identical steps. Technologies are not inherently proof of crime.','Use financial intelligence,beneficial-ownership checks and cross-border cooperation to identify professional networks. Blanket suspicion of remittance-dependent households can damage inclusion without improving detection.|For AP,enforcement should coordinate banks,cybercrime units and regulated intermediaries while preserving due process. Trace flows and predicate offences rather than relying solely on an app label or a cash transaction.','An encrypted message or digital token alone does not establish laundering;lawfulness depends on facts and applicable obligations.','How should anti-money-laundering systems respond to hybrid digital/informal networks?','DRISHTI',p='P2')
add('Economy','07 · Monetary institutions and public trust','A decade of flexible inflation targeting: judge outcomes carefully','The September magazine reviews the framework introduced in2016. This note does not independently certify a newly notified2026target or repeat a secondary article’s causal claims as settled fact.','Flexible targeting combines a stated price-stability objective with attention to growth.|Monetary transmission operates through financial conditions and expectations,but food and energy supply shocks can dominate near-term inflation.|Observed inflation changes cannot be attributed to the framework alone without considering fiscal,supply and global influences.','A target,a tolerance band,a forecast and actual inflation are distinct. Headline and core inflation also answer different questions.','Assess credibility,communication,accountability and the response horizon alongside growth and distributional effects. Interest rates cannot directly produce rain or resolve logistics blockages.|For AP households,food expenditure exposure can differ from the national average. Link state supply measures with national monetary policy without assuming a separate state repo rate.','A temporary supply-driven inflation rise does not by itself prove either total framework failure or absence of monetary responsibility.','How should flexible inflation targeting be evaluated in a supply-shock-prone economy?','DRISHTI',p='P2')
add('Environment','01 · Pollution and climate governance','Ozone protection and Kigali: two environmental problems connect','WorldOzoneDay on16September provides a revision link to the MontrealProtocol and KigaliAmendment. Exact2026theme and achievement percentages are not independently verified here.','The MontrealProtocol controls ozone-depleting substances such asCFCs andHCFCs.|HFCs generally do not deplete ozone but can be powerful greenhouse gases;Kigali addresses their phasedown.|Protecting stratospheric ozone reduces harmful ultraviolet exposure;it is not the same physical mechanism as reducing greenhouse warming.','The ViennaConvention supplies a cooperation framework;the MontrealProtocol provides control commitments. Stratospheric ozone differs from harmful ground-level ozone.','Successful refrigerant transition needs efficient equipment,safe alternatives,technician training and recovery/disposal systems. Replacing a refrigerant without improving energy efficiency can miss substantial climate benefits.|For AP buildings,cold chains and data centres,assess lifecycle leakage,electricity and safety together. Do not confuse a phasedown schedule with an immediate ban on every cooling appliance.','HFC climate concerns do not mean HFCs are the same ozone-depleting chemicals asCFCs.','What lessons does ozone cooperation offer for sustainable cooling?','DRISHTI',16,p='P2')
add('Environment','02 · Biodiversity and cryosphere','WorldRhinoDay: conservation differs across five species','The September compilation reviews WorldRhinoDay on22September and a conservation report. Original population tables and reported zero-poaching records were not independently inspected.','The five living rhino species are white,black,greater one-horned,Javan andSumatran.|India’s principal rhino conservation context is the greater one-horned rhino,with major habitat inAssam.|Poaching,habitat quality,fragmentation and small-population risks vary across species and landscapes.','Species count,population estimate,conservation category and annual poaching incidents are different indicators. Horn is largely keratin,not a scientifically established medicinal cure.','Combine habitat management,anti-trafficking enforcement,community participation and scientifically planned population management. A single year without reported poaching is not proof that long-term threats have ended.|For APPSC,locateKaziranga accurately without inventing a newAPwild rhino population. Conservation reporting needs dated baselines and transparent methods rather than unlabelled changing totals.','Five species does not mean five species naturally occur inIndia.','How can species recovery be evaluated beyond population totals?','DRISHTI',22,p='P2')
add('Environment','01 · Pollution and climate governance','Climate overshoot: a temporary breach can leave lasting damage','The magazine discusses UNEP’s LimitingOvershoot report. Exact probabilities,carbon-budget numbers and geopolitical membership claims were not independently checked against the primary report.','Overshoot describes warming rising above a threshold before later returning below it in a modelled pathway.|A single hot year and a sustained long-term warming level are not interchangeable measurements.|Some impacts,such as ecosystem loss and ice-sheet change,may not reverse simply because global average temperature later declines.','Carbon budgets depend on warming thresholds,probability,baseline and treatment of nonCO2forcing. Modelled pathways are conditional,not guaranteed forecasts.','Rapid emissions reductions limit peak warming and reliance on uncertain future removals. Methane mitigation can complement,not replace,sustainedCO2cuts.|For AP,link coastal risk,heat,water and resilient infrastructure to adaptation while avoiding a false claim that any annual threshold breach automatically terminates the ParisAgreement.','A planned return below1.5°Cdoes not imply every overshoot impact is harmless or reversible.','Why is limiting peak warming important even in pathways that later cool?','DRISHTI',p='P2')
add('Environment','02 · Biodiversity and cryosphere','Hanging glaciers: understand geometry before attributing collapse','Selected magazine passages discuss steep-slope ice and Himalayan hazards. Exact glacier counts and study methods were not independently inspected.','Hanging glaciers occupy steep or elevated positions from which ice can fall into lower valleys.|They can form through natural glacier geometry;it is incorrect to say every hanging glacier is created solely by recent climate change.|Warming and changing precipitation can alter stability,but collapse risk also depends on slope,fractures,bed conditions and local processes.','An ice avalanche,a glacial-lake outburst and a rainfall-driven flash flood are different initiating processes,although hazards can cascade.','Use satellite monitoring,field observations and downstream exposure maps to prioritise warning and land-use decisions. A mapped glacier is not proof of imminent collapse.|For AP,the transferable lesson is multi-hazard planning,not direct local hanging-glacier exposure. Distinguish Himalayan cryosphere processes from coastal and peninsular catchment risks in geography answers.','A hanging glacier is not necessarily a moraine-dammed lake,and not every collapse is aGLOF.','How should cascading mountain hazards inform risk-sensitive development?','DRISHTI',p='P2')
add('Science & Technology','01 · Ocean resources and environmental limits','Deep-sea minerals: exploration does not authorise commercial extraction','The magazine consolidates seabed-mineral security and ecological concerns. Exact contract counts,vehicle test depths and commercial statuses were not independently verified.','Polymetallic nodules,sulphides near hydrothermal systems and cobalt-rich crusts occur in different seabed settings.|The seabed beyond national jurisdiction is “theArea” underUNCLOS,and the InternationalSeabedAuthority has a specific mandate there.|Exploration,technology testing,an exploitation framework and an operating mining project are separate stages.','TheArea differs from a state’s maritime zones. UNCLOS institutions and national offshore law should not be collapsed into one permit.','Ecological uncertainty includes slow recovery,sediment plumes,noise and poorly characterised biodiversity. Strategic minerals justify serious research,not an assumption that any resource must immediately be mined.|For APcoastal/ocean-policy answers,distinguish national seabed interests from local port activity. Evaluate precaution,baseline science and monitoring alongside alternatives such as recycling and material substitution.','An exploration contract is not automatically a commercial exploitation licence.','How should mineral security be balanced with deep-ocean ecological uncertainty?','DRISHTI',p='P2')
add('Society & Welfare','03 · Evidence-based medicine','Stem-cell therapy: biological potential is not an approved cure','The September compilation discusses an advisory on approved versus experimental use. The original advisory and cited court judgment were not independently read;precise new legal holdings are not asserted.','Stem cells can self-renew and differentiate,but their capacities vary by cell type.|Haematopoietic stem-cell transplantation has established uses for specified blood disorders;that does not validate every marketed regenerative treatment.|Claims for conditions such asautism require rigorous research and applicable approvals rather than being treated as standard proven care.','Embryonic,adult and induced pluripotent cells are distinct. Scientific plausibility,safety,efficacy and regulatory authorisation are separate tests.','Protect patients through ethical review,informed consent,trial registration,adverse-event monitoring and truthful advertising. Vulnerable families need affordable evidence-based services,not unverified miracle-cure promises.|For AP,connect clinical oversight with disability support and grievance redress. This note is educational,not an individual treatment recommendation or a claim all cell-based interventions are equally approved.','A clinic’s commercial offer or patient testimonial is not proof of clinical efficacy.','How can healthcare governance protect patients from unproven regenerative treatments?','DRISHTI')
add('Science & Technology','02 · Responsible digital systems','AgenticAI: tool access increases the need for accountable control','Selected magazine passages discuss agentic misalignment and proposed industry safety institutions. Specific model anecdotes and a formally established new standards body were not independently verified.','AIagents can use tools and execute multi-step tasks,creating risks beyond a static text response.|Misalignment concerns actions or strategies diverging from intended goals and constraints;simulation results are not automatically real-world incident rates.|An industry proposal for testing or audits is not a binding public regulator or proof that all systems meet a safety standard.','Capability,autonomy,permissions and deployment context jointly determine risk. Openweights,opensource and transparent governance are not identical.','Use least-privilege access,human approval for consequential actions,sandboxing,logs and rollback. Independent evaluation should consider both dangerous capabilities and realistic failure modes.|For APdigital public services,protect personal data and preserve human responsibility for eligibility,payments and legal decisions. Vendor self-certification alone cannot replace public accountability or accessible appeals.','More autonomous task execution does not eliminate the deploying institution’s responsibility.','What safeguards should governAIagents acting within public-service systems?','DRISHTI')
add('Science & Technology','03 · Space science and mission engineering','Cosmic hydrogen: why the lunar far side attracts radio astronomy','The magazine discusses proposedCosmoCube andPRATUSH concepts. This is mission-design/science revision,not independently verified launch or successful signal detection.','Neutral hydrogen’s spin-flip transition has a rest wavelength near21cm.|Cosmic expansion redshifts early-universe signals to lower frequencies,where foregrounds and human radio interference complicate detection.|Lunar shielding can reduce terrestrial interference during suitable observing phases,but onboard equipment and calibration still matter.','CosmicDarkAges,CosmicDawn and reionisation are related but distinct periods. A radiometer measures radio signals,not an ordinary optical image of first stars.','Design must balance sensitivity,foreground modelling,radio quietness,power and data transmission. Proposed observations cannot be reported as discoveries before actual evidence is obtained.|ForPrelims,the lunar far side is not permanently dark:it receives sunlight during its cycle. Scientific interest comes from radio shielding,not absence of sunlight.','The21cmrest wavelength is not necessarily the wavelength received from the high-redshift early universe.','Explain the scientific and engineering case for lunar radio observations.','DRISHTI',p='P2')
add('Science & Technology','02 · Responsible digital systems','Data-centre cooling: efficiency metrics need defined boundaries','September magazine passages extend the August data-centre resource debate through cooling technologies. Capacity forecasts and per-rack heat totals were not independently certified.','Air cooling,direct-to-chip liquid cooling,rear-door heat exchangers and immersion cooling use different heat-removal architectures.|Evaporative systems can trade electricity savings against water consumption;climate and water quality affect feasibility.|Nearly allITelectricity eventually becomes heat,but facility load,ITload and installed grid capacity differ.','PUE compares total facility energy withITenergy;water-use metrics and carbon intensity provide additional,not interchangeable,information.','Optimise cooling under realistic weather,server density,reliability and drought conditions. A lowerPUEmay coexist with higher total water use or expanding absolute energy demand.|For AP,request site-specific water balances,heat-rejection plans,renewable sourcing and performance reporting. Liquid cooling does not automatically mean zero water use,and “efficient” equipment does not prove a project has low aggregate impact.','Power capacity inGWis not annual energy consumption inGWh.','How should data-centre sustainability be measured beyond a single efficiency ratio?','DRISHTI',p='P2')
add('Science & Technology','04 · Public health science','Salmonella: typhoid and non-typhoidal disease must not be conflated','The magazine discusses infection burden and antimicrobial resistance. A cited typhoid estimate is not repeated as if it measures all non-typhoidalSalmonella;the original study was not independently read.','S.Typhi andS.Paratyphi cause enteric fever;non-typhoidalSalmonella commonly causes gastroenteritis and can cause invasive disease.|Contaminated food/water and animal–food–environment pathways differ across infections.|Accurate diagnosis,safe water,food hygiene and appropriate clinical management matter alongside surveillance of antimicrobial resistance.','A bacterial genus,a serovar,a syndrome and a study’s case definition are different levels of classification. Vaccine indications are disease-specific.','Improve laboratory access,sample quality and reporting without treating every fever as typhoid. Antibiotic stewardship requires qualified assessment rather than indiscriminate self-medication.|For AP,connect water/sanitation and food handling with surveillance capacity. A typhoid vaccine does not automatically prevent everySalmonellainfection;precise schedules and treatment decisions require clinical guidance.','Typhoid case counts are not automatically non-typhoidalSalmonella counts.','How canOneHealth approaches reduce foodborne infection andAMR?','DRISHTI',p='P2')
add('Science & Technology','03 · Space science and mission engineering','Gaganyaan heat shielding: protect the vehicle through controlled material loss','Selected magazine passages discuss re-entry thermal protection. Exact flight dates,temperature claims and internal cabin conditions were not independently verified.','Ablative shields absorb and remove heat through processes including decomposition,char formation and material loss.|Re-entry heating is strongly linked to high-speed flow and compression/shock physics,not simply ordinary surface friction.|Shield validation involves materials,geometry,aerodynamics,structural integration and testing;an upcoming flight is not a completed mission.','Ablative,radiative and heat-sink protection use different mechanisms. A material’s test temperature is not automatically the crew’s ambient cabin temperature.','Safety requires reliable qualification across variable loads and off-nominal conditions. Redundancy and quality control matter as much as a successful single demonstration.|For exam answers,connect thermal protection to the broader human-spaceflight system:guidance,life support,recovery and validation. Do not repeat a high internal temperature as acceptable human comfort.','Sacrificial ablation is an intended protection mechanism,not necessarily a shield failure.','Why is re-entry engineering a central challenge for human spaceflight?','DRISHTI',p='P2')
add('Agriculture','03 · Recognition,rights and access','Women farmers: cultivation work and recorded ownership differ','The September compilation discusses independent recognition of women farmers. A claimed first-stateBill and exact beneficiary shares were not independently verified;the note focuses on the exclusion mechanism.','Women can cultivate,manage farms or work as unpaid family helpers without appearing as recorded landowners.|Land-linked eligibility and collateral requirements can restrict access to credit,extension,insurance and transfers.|Recognition certificates,tenancy rights,joint titles and scheme eligibility address different problems;none should be presumed operational nationwide from a magazine headline.','Worker,operator,tenant and owner are distinct categories. AgriculturalCensus operational holdings and legal ownership data are not interchangeable.','Improve access using appropriate evidence of cultivation,legal aid,gender-sensitive extension and transparent eligibility rules. Recognition should support agency and income,not merely add an administrative card.|For AP,connect women’s groups,tenant cultivation and land-record correction while protecting common/customary rights. Measure control over resources,service access and time burdens rather than only registrations.','High women’s agricultural participation does not prove a matching ownership share or automatic access to every benefit.','How can farmer recognition reduce gender-based exclusion in agricultural policy?','DRISHTI')
add('Society & Welfare','04 · Disability and lifecycle support','Post18disability support: rights do not end when school ends','The magazine reviews gaps in adult support,respite care and community living. This is thematic consolidation,not a verified newSeptemberpension entitlement.','Families may face discontinuities after school in vocational support,day services,assisted living and rehabilitation.|Unpaid caregiving can reduce employment and income,especially for women.|TheRPwDframework requires rights-based inclusion,but actual service availability and benefit eligibility need separate assessment.','Legal recognition,disability certification,service access and social protection are connected but distinct. Support should respect autonomy,consent and individual needs.','Build coordinated adult pathways across health,skills,local bodies and social welfare. Respite support and accessible information can reduce family crisis without assuming institutionalisation is the only solution.|For AP,link certification correction andUDIDwith community-based services and safe supported employment. Track waiting times,care burden and meaningful participation,not only cards issued.','Turning18does not erase disability rights;an identity card alone does not guarantee every needed service.','Design a lifecycle approach to disability support beyond school age.','DRISHTI')
add('Culture & History','01 · Transition to independence','InterimGovernment1946: a transitional executive,not the republic','September marks the2September1946formation anniversary,reviewed in the magazine. The precise1919/1935statutory-framework wording was not independently reconciled and is deliberately omitted.','JawaharlalNehru served asVicePresident of theViceroy’sExecutiveCouncil;theViceroy remained formal head.|The administration was part of the transition toward independence,while theConstituentAssembly had a different constitution-making function.|TheMuslimLeague initially stayed out and joined later in1946;executive participation did not resolve all constitutional disagreements.','An interim executive,a constituent body,a dominion government and a republican cabinet are distinct institutions and phases.','Locate the event withinCabinetMission negotiations,communal tensions and transfer-of-power arrangements. Avoid presenting the interim administration as already operating under the1950Constitution.|ForMains,examine both expanding Indian executive responsibility and remaining colonial constraints. Historical significance does not require an unverified precise legal-framework claim.','Nehru’sExecutiveCouncil role in1946is not identical to his later constitutional office asPrimeMinister of the republic.','Assess the role of the1946InterimGovernment in the transfer of power.','DRISHTI',2,p='P2')
add('Polity & Governance','04 · Electoral institutions and public trust','Party symbols: faction adjudication is not anti-defection adjudication','The magazine revisitsECI’s role in symbol disputes. A specific claimedpartyfreeze was not independently checked against theCommission’sorder and is withheld.','TheElectionSymbolsOrder1968provides a framework for disputes involving recognised-party factions.|Organisational rules,objectives and support within relevant wings can be important evidence.|Temporary freezing or alternative symbols must be tied to an actual order;not every faction dispute has the same legal outcome.','Article324,theSymbolsOrder and theTenthSchedule concern related but different institutional powers. Legislative disqualification and party-symbol entitlement are not interchangeable.','Transparent evidence,reasoned decisions and timely hearings matter for electoral fairness. A faction’s numerical claim should not substitute for lawful verification.|For APPSC,compare internal party democracy and voter clarity without inferring an unverified local outcome. ECI decisions remain subject to constitutional judicial scrutiny;“binding”does not mean immune to courts.','Winning a symbol dispute does not automatically decide every legislator’s anti-defection case.','How should electoral institutions balance timely symbol decisions and procedural fairness?','DRISHTI',p='P2')
add('Society & Welfare','05 · Skills and rural opportunity','DDU–GKY2.0: measure sustained work rather than training certificates','The September magazine uses the scheme’s2014launch anniversary to review placement-linked rural skills and the2.0guidelines. This is follow-through,not proof of a newSeptemberlaunch.','DDU–GKYis associated with theRuralDevelopmentMinistry and rural poor youth’s skill/employment pathways.|The reviewed2.0approach emphasises training,placement,retention,post-placement support and progression.|Geography,inclusion and local-industry demand affect outcomes;exact eligibility exceptions and achieved placement totals were not independently audited.','Training completion,job placement,retention,wage progression and self-employment viability are distinct indicators.','Design employer links,credible assessments and safe migration support before expanding seat counts. Incentives based only on placement can encourage short-lived or poorly matched jobs.|For APrural youth,connect training with local manufacturing,healthcare,green services and accessible transport. Track wage receipts,working conditions and durable progression rather than treating every certificate as a job.','An anniversary review does not establish thatDDU–GKY2.0was first launched inSeptember2026.','What makes placement-linked skilling produce sustained rural opportunity?','DRISHTI',25,p='P2')
add('Andhra Pradesh','01 · Aquaculture and farm support','AP cage-culture proposal: productivity needs reservoir safeguards','ETVBharat’s3SeptemberCabinet report places a cage-culture draft in the reviewed agenda. The original policy/GO was not inspected;reported consideration is not certified statewide operational permission.','Cage culture raises fish in enclosures within suitable water bodies,unlike a fully separate pond system.|Reservoir use can interact with drinking water,irrigation,capture fisheries and ecosystem functions.|Reported discussion of leases and regulation must be distinguished from final site-specific licences,carrying-capacity studies and beneficiary allotment.','Aquaculture output and water-body ecological capacity are different. Stocking density,feed,waste,oxygen and disease influence both productivity and environmental risk.','Use transparent site selection,water-quality monitoring and fisher participation. A profitable enterprise model can still create conflict if common-water access and traditional livelihoods are ignored.|ForAPPSC,connect cage culture with food security,value chains and public-water governance. Do not assume every reservoir is suitable or that aCabinetagenda item itself grants a lease.','Cage culture is not risk-free merely because it uses an existing water body.','Design safeguards for inclusive and sustainable reservoir aquaculture.','AP3',3,True)
add('Andhra Pradesh','01 · Aquaculture and farm support','AP mango support: a financing proposal is not money already paid','The3SeptemberCabinet report discusses₹281crore financing throughMARKFED for mango support. Original sanction,procurement accounts and farmer-level payment records were not inspected.','MARKFEDis a state cooperative marketing institution;the reported amount relates to financing for intervention.|Credit authorisation,a procurement decision,actual purchases and final farmer payments are separate stages.|Support must be assessed alongside varieties,quality,harvest timing,processing demand and the market-price collapse it seeks to address.','Price stabilisation,budget subsidy,working-capital borrowing and a loan guarantee create different cash flows and fiscal exposures.','Transparent procurement,weights,grading and timely payment determine whether distress relief reaches cultivators. Storage and processing capacity can reduce repeated emergency dependence.|For AP,examine who bears interest,stock losses and repayment risk. Do not describe₹281crore as a universal cash transfer or as verified expenditure already received by every mango grower.','A financing proposal is not audited procurement or completedDBT.','How can fruit-market interventions combine immediate relief with durable value-chain reform?','AP3',3,True)
add('Andhra Pradesh','01 · Aquaculture and farm support','AP tobaccoDBTproposal: trace eligibility,price risk and evidence','ETVBharat’s3Septemberreport describes a₹94crore direct-benefit-support proposal connected with tobacco farmers. Original eligibility rules,rate schedules and disbursement lists were not obtained.','DBTdescribes a delivery mechanism,not the policy’s full eligibility or cost-sharing design.|Auction dynamics,quality,export demand and grower registration can affect tobacco-sector distress.|ReportedCabinet consideration does not independently establish that every grower qualifies or that₹94crore has reached bank accounts.','A farmer-support measure and public-health tobacco control pursue different objectives;one should not silently erase the other.','Verify beneficiary records,exclusions,payment failures and grievance channels. Over time,diversification and stable alternative markets can reduce dependence on a volatile crop.|For APPSC,explain the tension between livelihood protection and health/social costs without inventing a new tax rule or guaranteed tobacco price. Separate reported relief from realised income and from long-run transition policy.','DBTdoes not mean universal eligibility or proof that the entire announced amount is disbursed.','How should governments balance tobacco-grower livelihoods with public-health objectives?','AP3',3,True)
add('Andhra Pradesh','02 · Irrigation and public works','Sangamam modernisation: distinguish a proposal from commissioned benefit','The3SeptemberCabinet report lists an approximately₹759.79crore proposal forSangamamBarrage modernisation inSangammandal,Nellore. No original sanction or detailed project report was independently read.','Modernisation may involve hydraulic reliability,mechanical systems and operational improvement,but exact approved components require the project documents.|An estimated project cost differs from administrative sanction,tender value,expenditure and completed physical progress.|Irrigation benefit depends on downstream conveyance,operating rules and available water,not a headline rupee figure alone.','A barrage diverts/regulates river flow differently from a large storage dam. Nominal command area and reliably irrigated area are not interchangeable.','Assess structural safety,flood conveyance,sediment,maintenance and procurement milestones. Publish measurable service outcomes and responsibility for corrective work.|For APPSC,connectNellore irrigation resilience with realistic cost and benefit appraisal. Do not claim the proposal has already delivered an additional verified acreage or completed a new barrage.','A reported modernisation proposal is not proof of completed works or a new water allocation.','How should irrigation modernisation be evaluated beyond announced project cost?','AP3',3,True)
add('Andhra Pradesh','02 · Irrigation and public works','VeligondaTBMequipment: disposal proceeds are not water delivery','TheCabinet report records₹11.63crore approval for disposal of tunnel-boring equipment associated withVeligonda. A linked article’s31Augustopening is not silently counted as a newSeptemberevent.','TBMequipment is used for mechanised tunnel excavation;completed tunnelling and full project operation are different milestones.|Asset disposal should follow transparent valuation,authority and tender/auction procedures.|A reported disposal value is not the project’s complete construction cost or independently verified final sale receipts.','Sunk project costs,remaining asset value and future maintenance obligations belong to different appraisal categories.','Document equipment condition,ownership,valuation and realised proceeds. A project’s irrigation value depends on reservoir,canal,clearance and operating readiness beyond removal of a machine.|For APPSC,link public-asset management withVeligonda’s broader implementation stages. Avoid converting aCabinetapproval about equipment into a claim that every command-area farmer has already received assured water.','₹11.63crore concerns reported equipment disposal,not the fullVeligondaproject budget.','Why should public infrastructure reviews distinguish asset disposal and service commissioning?','AP3',3,True,p='P2')
add('Andhra Pradesh','03 · Fiscal institutions and infrastructure finance','APTRANSCOguarantee proposal: a contingent liability is not free capital','The3SeptemberCabinet report includes consideration of a₹950crore guarantee fortransmission financing. No executed guarantee,loan agreement or treasury accounting was independently inspected.','A guarantee promises contingent payment if specified obligations are not met;it is not necessarily immediate budget expenditure.|The borrower’s debt-service capacity,project cash flows,guarantee fee and state exposure require separate review.|A proposal orCabinetdecision does not prove that the lender has disbursed the loan or that the transmission asset is commissioned.','Borrowing,guarantees,subsidies,equity injections and tariff revenue affect public finance through different channels.','Publish guaranteed exposures and stress-test repayment under demand,tariff and delay scenarios. Transmission reliability can justify investment,but financing must remain transparent and affordable.|For APPSC,connect utility balance sheets with broader fiscal risk rather than excluding all guaranteed borrowing from analysis. Count actual project performance and contingent exposure,not only the approval amount.','₹950crore guarantee consideration is not a₹950crore grant or proof of an immediate guarantee call.','How should states govern utility guarantees while funding reliable infrastructure?','AP3',3,True)
add('Andhra Pradesh','04 · Land use,housing and ecological safeguards','Nellore canal-land reclassification: retain the exclusions and buffer','TheHindu reports the3SeptemberCabinet decision to reclassify22.31acres from a62.70acre canal-related land extent for house sites. Original survey records andGOwere not inspected.','The report distinguishes vacant land from the active canal and operational/maintenance zones.|Active canal-related functions are excluded,and a20foot buffer is reported.|Reclassification,individual allotment,physical possession and final house construction are separate steps.','Revenue classification does not by itself establish absence of flood risk. Housing rights,public water infrastructure and environmental safeguards can overlap.','Verify cadastral boundaries,current drainage,flood pathways and safe access before allotment. Protect operational maintenance and assess whether the reported buffer is sufficient for actual site conditions.|For APPSC,use the exact22.31acre approved extent rather than implying all62.70acres were converted. Public transparency and reasoned grievance processes can reduce conflict and future displacement risk.','The decision is not conversion of the entire62.70acres or permission to obstruct the active canal.','How can housing policy on public land protect water infrastructure and disaster safety?','NELL',3,True)
add('Andhra Pradesh','05 · Policing and accountable communication','Four police commissionerates: institutional change needs readiness','SouthFirst’s23SeptemberCabinet report identifiesTirupati,Guntur,Kurnool andRajamahendravaram for new commissionerates. Original jurisdiction maps and commencement notifications were not inspected.','A commissionerate generally integrates urban police functions with designated executive powers under applicable law.|Cabinetapproval must be distinguished from operational notification,staffing,budgets and station-level boundaries.|The preciseBNSSsubsection reported in news was not independently reconciled and is not reproduced as verified law.','Police organisation,criminal procedure and judicial oversight remain distinct. Reorganisation does not eliminate constitutional rights or magistrate/court safeguards.','Assess urban growth,crime patterns,response times,staffing and citizen access before celebrating institutional expansion. Internal accountability and external complaints arrangements remain important.|For APPSC,locate the four cities accurately and ask how resources and specialised units will follow. Do not infer that every district is now a commissionerate or that approval itself proves reduced crime.','Four approved new commissionerates are not proof of completed jurisdictional rollout.','What makes urban policing reorganisation effective and accountable?','AP23',23,True)
add('Andhra Pradesh','05 · Policing and accountable communication','APinfluencerempanelment: public information must remain identifiable','The23SeptemberCabinet report describes a social-media-influencer policy for government outreach. The original laterGO,payment schedules and actual contracts were not read.','Reported empanelment is forone year,with up totwo additional annual extensions based on conditions.|Platform reach,performance and complaints matter to selection/continuation,but precise payment rates are not certified here.|Policy approval,empanelment,a work order,paid content and audited campaign outcomes are separate stages.','Government information,political campaigning,public advertising and a creator’s independent speech are not automatically the same activity.','Require conspicuous sponsorship disclosure,transparent selection,documented spending and protection against misleading claims. Reach metrics can be inflated and should not substitute for service uptake or factual accuracy.|For APPSC,assess administrative neutrality and public value without presuming all criticism is misinformation. Clear grievance and audit rules can preserve trust better than opaque government–creator relationships.','Cabinetapproval is not proof that every influencer has a paid contract or that all promoted content is independent speech.','Design accountability safeguards for government use of social-media influencers.','AP23',23,True)
add('Andhra Pradesh','06 · Investment and employment implementation','SIPBinvestmentpipeline: proposals and jobs remain conditional','The23SeptemberCabinet report states investment approvals of₹22,177.84crore with19,739potentialjobs. Component sector figures do not fully reconcile;an invented breakdown is deliberately omitted.','SIPBfacilitates investment consideration;project approval is not an audited financial closure or operating factory.|Potential jobs are projections,not verified current employment.|Land,utilities,clearances,financing,construction and production create a chain of implementation milestones.','Intentions,MoUs,approvals,realised capital expenditure and sustained employment are different investment indicators.','Track project-level timelines,incentive obligations,water/power demand and actual payroll. Fiscal support should have transparent conditions,performance checks and clawback where lawful.|For APPSC,connect industrial policy with regional distribution,skill fit and environmental capacity. Do not divide announced cost by projected jobs and treat the resulting ratio as a realised social cost–benefit calculation.','₹22,177.84crore is an approved pipeline figure,not certified realised investment;19,739jobs are potential.','How should states assess industrial investment beyond approval totals?','AP23',23,True)
add('Andhra Pradesh','06 · Investment and employment implementation','APenergyapprovals: capacity needs network and commercial viability','SouthFirst’s23Septemberreport separately identifies₹5,176.56crore of energy projects. Original project sanctions,capacity schedules and purchase agreements were not inspected.','The reported portfolio includes solar,hybrid and storage-linked activity;these technologies have different operating characteristics.|An investment value does not by itself revealMWcapacity,MWhstorage,annual output or a guaranteed tariff.|Project approval is not financial closure,grid connection or commercial operation.','Generation,transmission,storage and power purchase obligations are interdependent but distinct. Variable output must be integrated into dispatch and reliability planning.','Evaluate land,water,siting,evacuation,storage duration and payment risk. Low headline tariffs can conceal integration costs if studies and contracts are incomplete.|For APPSC,link this pipeline with the nationalGECIIIframework as analysis,not a verified project-specific central allocation. Avoid adding unreconciled sector figures to manufacture a new investment total.','₹5,176.56crore is notMWcapacity or proof of operating power supply.','What conditions make approved renewable projects deliver reliable and affordable electricity?','AP23',23,True)
add('Andhra Pradesh','02 · Irrigation and public works','CIIPcostrevision: explain scope and uncertainty before celebrating escalation','The23SeptemberCabinet report records aChintalapudiIrrigationProject revision from₹904crore to₹1,548.98crore for the cited scope. Original revised estimate and detailed cost components were not obtained.','The reported increase is₹644.98crore,about71.35%over the cited baseline.|The abbreviated report does not independently establish that the figure represents every cost of the entire multi-component project.|A revised approved estimate differs from expenditure,tendered value,physical completion and dependable irrigation benefit.','Cost escalation can reflect scope,prices,delays or design changes;the cause cannot be inferred from arithmetic alone.','Publish component-level reasons,remaining work,procurement milestones and benefit assumptions. Independent review should separate justified changes from avoidable delay or weak initial appraisal.|For APPSC,report the two cited figures accurately and avoid calling their difference confirmed waste. Link construction progress with water availability,distribution infrastructure and maintenance responsibility.','A71.35%increase in the cited estimate is not proof of an equal increase in irrigated area or corruption.','How can revised irrigation estimates be made transparent and accountable?','AP23',23,True)
add('Andhra Pradesh','03 · Fiscal institutions and infrastructure finance','APDA/DRdecision: accrual,cash payment and arrears have different dates','The23SeptemberCabinet report gives differentDearnessAllowance/DearnessRelief changes and arrears timing under separate pay frameworks. Original finance orders were not independently inspected.','Reported DA/DRincreases include2.73%for the relevant state framework and1.82%for the corresponding central-pay group.|The report links retrospective effect to different2024/2025periods,cash effect toSeptember2026and arrears to2027/2028;precise employee-category calculations require the operative order.|Not every group shares a rate,base pay,effective date or arrears schedule.','DAindexation is distinct from basic-pay revision,bonus and pension-rule change. Accrued liability and immediate cash expenditure can diverge.','Clear payroll communication reduces confusion about entitlement and bank receipts. Budget analysis should include deferred arrears,category coverage and implementation risk.|For APPSC,explain the fiscal/social-protection balance without promising a uniform take-home increase. The reviewed news report does not replace employee-specific payroll or pension advice.','Retrospective entitlement does not mean the entire arrears amount was paid inSeptember.','Why should public-pay decisions distinguish effective date,cash effect and arrears liability?','AP23',23,True)
add('Andhra Pradesh','07 · Commodity markets and consumer protection','Onion/turdalintervention: requests,orders and delivered supply differ','TheHindu’s4Septemberreport covers the3Septembersubcommittee response to essential-commodity prices. Original supply orders and delivery accounts were not inspected.','Onions at₹35perkg through intervention channels were reported;the government approachedNCCFfor support.|The reported1.20lakhtonnes of turdal is a requested allocation,not verified delivered stock.|The report records a10,000tonnesKNMrice procurement order,not proof that the full amount was procured and sold.','Public procurement,allocation,transport,retail distribution and final consumer access are separate stages. Intervention retail prices need not equal every private-market price.','Target stocks to real shortages,maintain quality and publish sales/availability data. Short-term market relief should be combined with logistics,storage and supply forecasting.|For APPSC,analyse farmer–consumer trade-offs and fiscal losses without converting every announced measure into completed supply. Quantity units and request status are essential for accuratePrelimsquestions.','1.20lakhtonnes is a turdalrequest,not confirmed delivery;₹35perkg is not automatically a universal price-control order.','How can commodity-market interventions protect consumers without distorting long-run supply?','PRICE',3,True)
add('Andhra Pradesh','04 · Land use,housing and ecological safeguards','APapplication: make integrated land records contestable and inclusive','This is an originalAPpolicy application of theSeptemberDILRMP3.0roadmap,not a separate newly announced APscheme or verified completed state rollout.','Parcel identifiers can help link maps,registration and revenue cases,but underlying discrepancies need correction.|Mutation processes,registered documents and adjudicated title should retain their distinct legal meanings.|Service integration should include accessible notice,assisted filing,auditable changes and meaningful appeal.','Digitisation improves information flow;it does not automatically confer conclusive title or extinguish tenancy,community or customary claims.','Prioritise high-conflict records and test whether map geometry matches ground reality before scaling automation. Protect personal information and establish who is responsible when agencies disagree.|For APPSC,evaluate citizen outcomes:less repeat travel,fewer erroneous refusals,faster correction and preserved rights. Link toULPINwithout claiming a newAP-specific central grant or a completedLandStackdeployment.','This is analytical application of a national roadmap,not an independently verified SeptemberAPannouncement.','Design an inclusive implementation framework for integrated land governance inAndhraPradesh.','DIL,PRS',ap=True,precision='month')
add('Andhra Pradesh','08 · State energy-system strategy','APapplication: plan storage and transmission around usable service','This is originalAPanalysis linking the30SeptemberGECIIIapproval to state-system planning. It does not certify a specific APallocation or commissioned state project.','Grid studies must identify congestion,renewable profiles,load and suitable storage services.|GWpower andGWhenergy must be specified together when storage duration matters;50GWhnational support is not anAP-specific capacity target.|Transmission projects require right-of-way,procurement,commissioning and operating arrangements beyond aCabinetapproval.','Resource adequacy,frequency services,energy shifting and congestion management are distinct functions. A battery’s nameplate energy does not guarantee unlimited discharge duration.','Compare storage cycling,degradation,safety,replacement and revenues with alternatives such as network strengthening and demand response. Transparent cost allocation protects consumers from poorly matched investments.|For APPSC,connect industry,agriculture,rooftop solar andDISCOMfinances. Measure reliability and delivered renewable use rather than counting approvals;retain national-versus-state and capacity-versus-energy distinctions.','A national programme is not evidence thatAPhas received all its funding or achieved135GWof new generation.','How shouldAndhraPradesh integrate renewable power,storage and transmission planning?','GEC',30,True)

assert len(J)==60 and sum(n['ap'] for n in J)==16
# Typography corrections affect human prose only, never IDs, URLs, keys or numbers.
import re
protected=['P2P','P2M','P2PM','C2','CO2','2.0','3.0']
terms=['Government','Committee','Protection','Department','Development','President','Minister','Commission','Council','Bank','Supreme','Court','Social','Security','Executive','Constituent','Assembly','Interim','Cabinet','Mission','Vice','Prime','Rural','Management','Industry','Safety','World','Day','Steel','Special','Drawing','Facility','Standing','Deposit','Bhu','Aadhaar','Bamboo','Rhino','Ozone','Radio','Dark','Ages','Dawn','International','Seabed','Authority','East','Coast','North','South','New','Delhi','Andhra','Pradesh','Dearness','Allowance','Relief','State','Transmission','Utilities','Acceptance','Necessity','Food','Systems','Code','Chapter']
replacements={'GreenEnergyCorridor':'Green Energy Corridor','LandStack':'LandStack','GrowthModel':'Growth Model','perquintal':'per quintal','pertonne':'per tonne','perminute':'per minute','perkg':'per kg','all3chunksread':'all 3 chunks read','one year':'one year','turdal':'tur dal','onion/tur':'onion/tur','Post18disability':'Post 18 disability','InterimGovernment':'Interim Government','APinfluencerempanelment':'AP influencer empanelment','APenergyapprovals':'AP energy approvals','APDA/DRdecision':'AP DA/DR decision','APTRANSCOguarantee':'AP TRANSCO guarantee','SIPBinvestmentpipeline':'SIPB investment pipeline','TBMequipment':'TBM equipment','tobaccoDBTproposal':'tobacco DBT proposal','APapplication':'AP application','RhinoDay':'Rhino Day','OzoneDay':'Ozone Day','Sangammandal':'Sangam mandal','Veligondaproject':'Veligonda project','CosmicDarkAges':'Cosmic Dark Ages','CosmicDawn':'Cosmic Dawn','PowerSystems':'Power Systems','previou':'previou'}
acronyms=['DDU–GKY','DILRMP','MARKFED','DDU','EPFO','GEC','PIB','PRS','FAQ','DFS','UPI','MDR','CAD','GDP','FDI','FPI','CBRN','DAC','IBBI','IRDAI','AI','ECI','TRAI','ULPIN','NCCF','KNM','SIPB','TRANSCO','DISCOM','BNSS','CPD','FSSA','HCFC','CFC','HFC','UNCLOS','FATF','DFCCIL','DDU','UDID','RPwD','TBM','CIIP','MSP','MoU','GO','DBT','APPSC','AP','EU','FTA','GW','GWh','MW','MWh','UNEP','UN','AMR','IT','PUE']
def clean(s):
 for a,b in replacements.items():s=s.replace(a,b)
 for i,x in enumerate(protected):s=s.replace(x,f'§{chr(65+i)}§')
 # Explicit word list splits fused proper-name components without editing identifiers.
 for x in sorted(set(terms+acronyms),key=len,reverse=True):
  s=re.sub(r'(?<=[a-z])('+re.escape(x)+r')',r' \1',s)
  s=re.sub('('+re.escape(x)+r')(?=[a-z])',r'\1 ',s)
 s=re.sub(r'(?<=[A-Za-z₹])(?=\d)',' ',s)
 s=re.sub(r'(?<=\d)(?=[A-Za-z])',' ',s)
 s=re.sub(r'(?<=[%°])(?=[A-Za-z])',' ',s)
 s=re.sub(r'(?<=[,;])(?=[A-Za-z₹])',' ',s)
 s=re.sub(r'(?<=[.!?:])(?=[A-Z₹])',' ',s)
 # Curated month/measurement boundaries; common titles stay conventional.
 s=re.sub(r'(?<=[a-z])(September|October|November|January|April|June|August|May|July|February|March|December)',r' \1',s)
 for i,x in enumerate(protected):s=s.replace(f'§{chr(65+i)}§',x)
 return re.sub(r' +',' ',s).strip()
for n in J:
 for k in ['title','why','static_link','trap','mains','status','evidence_access']:n[k]=clean(n[k])
 for k in ['facts','analysis']:n[k]=[clean(t) for t in n[k]]
for k,v in S.items():
 if k.startswith('E16-'):v[0]=clean(v[0])
N.extend(J)
for name,obj in [('notes.json',N),('sources.json',S),('source-access.json',A)]:
 (R/'data'/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
print('Edition16 authored:',len(J),'notes;',sum(n['ap'] for n in J),'AP; totals',len(N),len(S))
